use crate::types::{ColorOrder,LineColour,LineMetadata};
pub fn extract_by_colour(text:&str,metadata:&[LineMetadata],colours:&[LineColour],order:ColorOrder)->String{if colours.is_empty(){return String::new()}let lines:Vec<&str>=text.split('\n').collect();match order{ColorOrder::Document=>lines.iter().enumerate().filter_map(|(i,l)|metadata.get(i).filter(|m|colours.contains(&m.colour)).map(|_|l.trim_end_matches('\r').trim_end().to_owned())).collect::<Vec<_>>().join("\n"),ColorOrder::Grouped=>{let mut groups=Vec::new();for c in colours{let mut lines_out=Vec::new();for(i,l)in lines.iter().enumerate(){if metadata.get(i).is_some_and(|m|m.colour==*c){lines_out.push(l.trim_end_matches('\r').trim_end().to_owned())}}
if !lines_out.is_empty(){groups.push(format!("# {}\n{}",c.name(),lines_out.join("\n")))}}groups.join("\n\n")}}}
